  // ═════════ ESPAGNOL : ser ou estar, pronoms ═════════
  L('lespagnol', 'es-ser', {
    fr:[
      Q('« La fête est à huit heures » :', 'La fiesta es a las ocho.', 'La fiesta está a las ocho.', 'Pour un événement (heure, lieu), on emploie « ser ». 🎉', 'La fiesta hay a las ocho.', '« Hay » dit que quelque chose existe. 📍', 'La fiesta son a las ocho.', 'La fête est au singulier : es. 🔢', 'Ser : heure et lieu d’un événement.'),
      Q('« La porte est ouverte » :', 'La puerta está abierta.', 'La puerta es abierta.', 'C’est un état, pas une caractéristique : estar. 🚪', 'La puerta está abierto.', 'Puerta est féminin : abierta. 👩', 'La puerta tiene abierta.', 'La porte n’a rien ! 🙃', 'État résultant d’une action : estar + participe.'),
      Q('« Il est médecin » :', 'Es médico.', 'Está médico.', 'Une profession, c’est une identité : ser. 🩺', 'Es un médico.', 'Sans adjectif, on ne met pas d’article. 🧩', 'Hay médico.', 'Non. 📍', 'Ser + profession, sans article.'),
      Q('« Le café est froid » (il a refroidi) :', 'El café está frío.', 'El café es frío.', 'C’est un état passager : estar. ☕', 'El café está fría.', 'Café est masculin : frío. 🧔', 'El café tiene frío.', 'Le café n’a pas froid ! 🥶', 'Estar : un état qui peut changer.'),
      Q('« Nous sommes à Séville » :', 'Estamos en Sevilla.', 'Somos en Sevilla.', 'Pour situer une personne : estar. 🗺️', 'Estamos a Sevilla.', 'Avec estar, le lieu se dit avec « en ». 📍', 'Hay en Sevilla.', 'Non. 🙅', 'Estar + en + lieu.'),
      Q('« Tu es très gentil » :', 'Eres muy amable.', 'Estás muy amable.', 'C’est un trait de caractère : ser. 😊', 'Es muy amable.', 'Avec « tú », c’est « eres ». 👤', 'Eres mucho amable.', 'Devant un adjectif : muy. 📏', 'Ser : caractère, personnalité.'),
      Q('« Je te le donne » :', 'Te lo doy.', 'Lo te doy.', 'Le complément indirect passe devant : te lo. 🔁', 'Te le doy.', 'Pour « le » (objet), on dit « lo ». 📦', 'Doy te lo.', 'Les pronoms vont devant le verbe conjugué. ⬅️', 'Ordre : indirect + direct + verbe.'),
      Q('« Donne-le-moi » :', 'Dámelo.', 'Dame lo.', 'À l’impératif, les pronoms s’attachent au verbe. 🔗', 'Lo dame.', 'À l’impératif affirmatif, ils vont après. ➡️', 'Dalo me.', 'L’ordre est me + lo. 🔁', 'Accent écrit pour garder l’accent tonique : dá-me-lo.'),
      Q('« Ils sont contents » :', 'Están contentos.', 'Son contentos.', 'Un sentiment passager : estar. 😀', 'Están contento.', 'Ils sont plusieurs : contentos. 👥', 'Tienen contentos.', 'Non. 🙃', 'Estar : humeur, état d’esprit.'),
      Q('« C’est mon frère » :', 'Es mi hermano.', 'Está mi hermano.', 'Identifier quelqu’un : ser. 👦', 'Es mío hermano.', 'Devant le nom : mi. 🧩', 'Hay mi hermano.', 'Non. 📍', 'Ser : identité.'),
      Q('« Il est en train de dormir » :', 'Está durmiendo.', 'Es durmiendo.', 'La forme progressive se fait avec estar. 😴', 'Está dormiendo.', 'Dormir change de voyelle : durmiendo. 🔤', 'Está a dormir.', 'C’est une tournure portugaise. 🇵🇹', 'Estar + gérondif.'),
      Q('« La table est en bois » :', 'La mesa es de madera.', 'La mesa está de madera.', 'La matière, c’est une caractéristique : ser. 🪵', 'La mesa es en madera.', 'La matière se dit avec « de ». 🧩', 'La mesa hay madera.', 'Non. 🙅', 'Ser de + matière.'),
      Q('« Je le leur dis » :', 'Se lo digo.', 'Le lo digo.', 'Devant lo, le / les devient se. 🔄', 'Les lo digo.', 'Devant lo, les devient se. 🔄', 'Lo les digo.', 'L’indirect passe devant. ⬅️', '« le / les » + lo → se lo.'),
      Q('« Elle est intelligente » :', 'Es inteligente.', 'Está inteligente.', 'Une qualité durable : ser. 🧠', 'Es inteligenta.', 'L’adjectif ne change pas au féminin. 🔤', 'Hay inteligente.', 'Non. 🙅', 'Les adjectifs en -e sont identiques au masculin et au féminin.'),
      Q('« Nous sommes mardi » :', 'Hoy es martes.', 'Hoy está martes.', 'Pour la date et le jour : ser. 📅', 'Hoy son martes.', 'Le jour est au singulier. 🔢', 'Hoy hay martes.', 'Non. 🙅', 'On peut aussi dire « Estamos a martes ».'),
      Q('« Je lui parle » (à Marie) :', 'Le hablo.', 'La hablo.', 'Complément indirect : le, même au féminin. 👩', 'Lo hablo.', '« Lo » est un complément direct. 📦', 'Hablo le.', 'Le pronom va devant le verbe conjugué. ⬅️', 'Hablar a alguien : complément indirect.')
    ],
    en:[
      Q('“The party is at eight o’clock”:', 'La fiesta es a las ocho.', 'La fiesta está a las ocho.', 'For an event (time, place), Spanish uses “ser”. 🎉', 'La fiesta hay a las ocho.', '“Hay” says that something exists. 📍', 'La fiesta son a las ocho.', 'The party is singular: es. 🔢', 'Ser: time and place of an event.'),
      Q('“The door is open”:', 'La puerta está abierta.', 'La puerta es abierta.', 'It is a state, not a characteristic: estar. 🚪', 'La puerta está abierto.', 'Puerta is feminine: abierta. 👩', 'La puerta tiene abierta.', 'The door does not own anything! 🙃', 'A state resulting from an action: estar + participle.'),
      Q('“He is a doctor”:', 'Es médico.', 'Está médico.', 'A job is an identity: ser. 🩺', 'Es un médico.', 'With no adjective, no article. 🧩', 'Hay médico.', 'No. 📍', 'Ser + job, with no article.'),
      Q('“The coffee is cold” (it has cooled down):', 'El café está frío.', 'El café es frío.', 'It is a passing state: estar. ☕', 'El café está fría.', 'Café is masculine: frío. 🧔', 'El café tiene frío.', 'The coffee isn’t feeling chilly! 🥶', 'Estar: a state that can change.'),
      Q('“We are in Seville”:', 'Estamos en Sevilla.', 'Somos en Sevilla.', 'To locate a person: estar. 🗺️', 'Estamos a Sevilla.', 'With estar, the place takes “en”. 📍', 'Hay en Sevilla.', 'No. 🙅', 'Estar + en + place.'),
      Q('“You are very kind” (to a friend):', 'Eres muy amable.', 'Estás muy amable.', 'It is a personality trait: ser. 😊', 'Es muy amable.', 'With “tú”, it is “eres”. 👤', 'Eres mucho amable.', 'Before an adjective: muy. 📏', 'Ser: character, personality.'),
      Q('“I give it to you”:', 'Te lo doy.', 'Lo te doy.', 'The indirect object comes first: te lo. 🔁', 'Te le doy.', 'For “it” (object), use “lo”. 📦', 'Doy te lo.', 'The pronouns go before the conjugated verb. ⬅️', 'Order: indirect + direct + verb.'),
      Q('“Give it to me”:', 'Dámelo.', 'Dame lo.', 'In the imperative, the pronouns are attached to the verb. 🔗', 'Lo dame.', 'In the affirmative imperative, they come after. ➡️', 'Dalo me.', 'The order is me + lo. 🔁', 'A written accent keeps the stress: dá-me-lo.'),
      Q('“They are happy”:', 'Están contentos.', 'Son contentos.', 'A passing feeling: estar. 😀', 'Están contento.', 'There are several of them: contentos. 👥', 'Tienen contentos.', 'No. 🙃', 'Estar: mood, state of mind.'),
      Q('“This is my brother”:', 'Es mi hermano.', 'Está mi hermano.', 'Identifying someone: ser. 👦', 'Es mío hermano.', 'Before the noun: mi. 🧩', 'Hay mi hermano.', 'No. 📍', 'Ser: identity.'),
      Q('“He is sleeping”:', 'Está durmiendo.', 'Es durmiendo.', 'The progressive form uses estar. 😴', 'Está dormiendo.', 'Dormir changes its vowel: durmiendo. 🔤', 'Está a dormir.', 'That is a Portuguese structure. 🇵🇹', 'Estar + gerund.'),
      Q('“The table is made of wood”:', 'La mesa es de madera.', 'La mesa está de madera.', 'The material is a characteristic: ser. 🪵', 'La mesa es en madera.', 'The material takes “de”. 🧩', 'La mesa hay madera.', 'No. 🙅', 'Ser de + material.'),
      Q('“I tell it to them”:', 'Se lo digo.', 'Le lo digo.', 'Before lo, le / les becomes se. 🔄', 'Les lo digo.', 'Before lo, les becomes se. 🔄', 'Lo les digo.', 'The indirect object comes first. ⬅️', '“le / les” + lo → se lo.'),
      Q('“She is clever”:', 'Es inteligente.', 'Está inteligente.', 'A lasting quality: ser. 🧠', 'Es inteligenta.', 'The adjective does not change in the feminine. 🔤', 'Hay inteligente.', 'No. 🙅', 'Adjectives ending in -e are the same for masculine and feminine.'),
      Q('“It’s Tuesday today”:', 'Hoy es martes.', 'Hoy está martes.', 'For the date and the day: ser. 📅', 'Hoy son martes.', 'The day is singular. 🔢', 'Hoy hay martes.', 'No. 🙅', 'You can also say “Estamos a martes”.'),
      Q('“I speak to her” (to Marie):', 'Le hablo.', 'La hablo.', 'Indirect object: le, even for a woman. 👩', 'Lo hablo.', '“Lo” is a direct object. 📦', 'Hablo le.', 'The pronoun goes before the conjugated verb. ⬅️', 'Hablar a alguien: indirect object.')
    ]
  });

